INSERT INTO `components` (`id`, `code`, `title`, `short_title`, `category`, `total_indicators`, `max_score`, `description`) VALUES (1, 'K1', 'Usaha Pengembangan Madrasah', 'Pengembangan Madrasah', 'Penilaian Tahunan & 4 Tahunan', 25, 100, 'Struktur organisasi, personalia, pedoman kerja, inovasi pembelajaran, kemitraan, pemenuhan 8 SNP, unit layanan khusus, dan sistem informasi TIK.');
