INSERT INTO `components` (`id`, `code`, `title`, `short_title`, `category`, `total_indicators`, `max_score`, `description`) VALUES (3, 'K3', 'Pengembangan Kewirausahaan', 'Kewirausahaan', 'Penilaian Tahunan & 4 Tahunan', 12, 48, 'Inovasi madrasah, budaya berpikir kreatif, pemberdayaan potensi produktif, penumbuhan jiwa kewirausahaan, bank ide, dan pemecahan masalah kelembagaan.');
INSERT INTO `components` (`id`, `code`, `title`, `short_title`, `category`, `total_indicators`, `max_score`, `description`) VALUES (4, 'K4', 'Supervisi Kepada Guru dan Tenaga Kependidikan', 'Supervisi Guru & Tendik', 'Penilaian Tahunan & 4 Tahunan', 11, 44, 'Penyusunan program supervisi akademik, pengembangan instrumen, pra-observasi, pemantauan pembelajaran, refleksi pasca-observasi, dan tindak lanjut PKB.');
